import{_ as a,H as t,f as s,i as E}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"加餐 | 集中答疑：详解iOS环境搭建","description":"","frontmatter":{},"headers":[{"level":2,"title":"Homebrew","slug":"homebrew","link":"#homebrew","children":[]},{"level":2,"title":"Node 和 NPM","slug":"node-和-npm","link":"#node-和-npm","children":[]},{"level":2,"title":"Watchman","slug":"watchman","link":"#watchman","children":[]},{"level":2,"title":"Ruby","slug":"ruby","link":"#ruby","children":[{"level":3,"title":"Gem 和 Bundler","slug":"gem-和-bundler","link":"#gem-和-bundler","children":[]}]},{"level":2,"title":"Xcode","slug":"xcode","link":"#xcode","children":[{"level":3,"title":"CocoaPods","slug":"cocoapods","link":"#cocoapods","children":[]}]},{"level":2,"title":"新建项目","slug":"新建项目","link":"#新建项目","children":[]},{"level":2,"title":"启动项目","slug":"启动项目","link":"#启动项目","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ReactNative新架构实战课/加餐｜集中答疑：详解iOS环境搭建.md","filePath":"ReactNative新架构实战课/加餐｜集中答疑：详解iOS环境搭建.md","lastUpdated":1795533704000}'),i={name:"ReactNative新架构实战课/加餐｜集中答疑：详解iOS环境搭建.md"};function n(p,e,A,o,l,c){return t(),s("div",null,[...e[0]||(e[0]=[E(`<h1 id="加餐-集中答疑-详解ios环境搭建" tabindex="-1">加餐 | 集中答疑：详解iOS环境搭建 <a class="header-anchor" href="#加餐-集中答疑-详解ios环境搭建" aria-label="Permalink to &quot;加餐 | 集中答疑：详解iOS环境搭建&quot;">​</a></h1><p>你好，我是蒋宏伟。这节课我们来做一次集中答疑。</p><p>我在后台留言里见到的最多的问题就是搭建环境卡住了，走不下去。为了方便新同学学习React Native，更快地搭建好环境，今天我会从头到尾带你搭建一套新环境，帮助你快速上手。</p><p>先说结论：没有畅通无阻的网络，搭建 React Native 环境是较为困难的，但并非不可能。</p><p>在这节课中，我使用的是 MacBook Pro 2016 款，系统版本是 macOS Monterey。我参考的是React Native 0.71 版的官方文档，搭建的 iOS 环境。在按照官方文档搭建的过程中，我也遇到了较多的网络问题，但所有问题都通过镜像的方式解决了。</p><p>下面我就具体展示下我的搭建步骤，供你参考。如果遇到更多问题，欢迎给我留言。</p><h2 id="homebrew" tabindex="-1">Homebrew <a class="header-anchor" href="#homebrew" aria-label="Permalink to &quot;Homebrew&quot;">​</a></h2><p>第一步是安装 Homebrew。Homebrew 是 Mac OS 的一个软件包管理器。</p><p>React Native 官方文档中，给了我们一个 Homebrew 的安装地址，从该地址可以进入Homebrew 官方文档。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/1.png" alt=""></a></p><p>该文档中会有如下命令，但执行命令后的结果会报错。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ /bin/bash -c &quot;$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/H</span></span></code></pre></div><p>报错内容如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/2.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报错的内容是 unable to access github，也就是访问不到 GitHub 地址。在后面还有非</span></span></code></pre></div><p>常多的类似网络报错。在这里，我就不再一一列举了。解决方案都是类似的，要么保持自己的网络畅通，要么使用相关的镜像源。</p><p>在知乎上有位大牛提供了 Homebrew 镜像源及工具，你可以通过如下命令一键安装。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ /bin/zsh -c &quot;$(curl -fsSL https://gitee.com/cunkai/HomebrewCN/raw/master/Homebr</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/3.png" alt=""></a></p><p>安装完成后，重启当前 Terminal，brew 就安装成功了。你可以运行如下命令，检查它是否安装成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew --version</span></span>
<span class="line"><span>Homebrew 3.6.15</span></span></code></pre></div><h2 id="node-和-npm" tabindex="-1">Node 和 NPM <a class="header-anchor" href="#node-和-npm" aria-label="Permalink to &quot;Node 和 NPM&quot;">​</a></h2><p>第二步是安装 Node 和 NPM。</p><p>Node 是 React Native 应用程序中，JavaScript 相关服务的运行环境，比如构建服务就是通过Node 环境提供的。安装的 Node，会自带 NPM 包管理器，它将帮助我们管理相关依赖。</p><p>我们可以通过 Homebrew 来安装 Node。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew install node</span></span></code></pre></div><p>安装完成后，你可以通过如下命令检查 Node 和 NPM 是否安装成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ node --version</span></span>
<span class="line"><span>$ npm --version</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/4.png" alt=""></a></p><p>安装完 NPM 后，为保证后续网络的畅通，你需要将 NPM 的 registry 设置为淘宝源。切换命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx nrm use taobao</span></span></code></pre></div><h2 id="watchman" tabindex="-1">Watchman <a class="header-anchor" href="#watchman" aria-label="Permalink to &quot;Watchman&quot;">​</a></h2><p>第三步，是安装一个名为 Watchman 的工具。它是由 Facebook 开发的一个工具，只要你的文件有一些变化，它就会自动重新运行你的项目。</p><p>我们使用 Homebrew 来安装 watchman。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew install watchman</span></span></code></pre></div><p>安装完成后，通过如下命令检查是否安装成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ watchman --version</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/5.png" alt=""></a></p><h2 id="ruby" tabindex="-1">Ruby <a class="header-anchor" href="#ruby" aria-label="Permalink to &quot;Ruby&quot;">​</a></h2><p>第四步，要安装的是 Ruby。</p><p>Ruby 是一种常用编程语言。在 React Native iOS 应用的依赖管理中会使用到它。Mac 电脑上默认集成了 Ruby，但却和 React Native 所依赖的 Ruby 版本有些不一致。因此，你需要通过rbenv 对 Ruby 进行版本管理，就像使用 NVM 工具用于管理 Node 的版本一样。</p><p>首先，你可以运行如下命令查看当前的 Ruby 版本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ruby --version</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/6.png" alt=""></a></p><p>系统自带的 Ruby 是 2.6.10 版本，而 React Native 0.71 所依赖的 Ruby 版本是 2.7.6。因此，我们需要使用 rbenv 将 Ruby 版本切换到 2.7.6。</p><p>接着，你可以使用 Homebrew 安装 rbenv，安装命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew install rbenv ruby-build</span></span>
<span class="line"><span>安装完成后，运行 init 命令。运行完成后，它会提示你需要在 .zshrc 文件中执行 rbenv</span></span>
<span class="line"><span>init 命令，因此你需要根据提示，使用 echo 将 init 命令添加到 Terminal 启动前。以保</span></span></code></pre></div><p>障 Terminal 启动时，rbenv 会生效。相关命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rbenv init</span></span>
<span class="line"><span># 每人的提示信息不一定相同，根据提示信息进行相关操作</span></span>
<span class="line"><span>$ echo &#39;eval &quot;$(rbenv init - zsh)&quot;&#39; &gt;&gt; ~/.zshrc</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/7.png" alt=""></a></p><p>命令执行完成后，重启 Terminal，安装并切换到 React Native 所依赖的 Ruby 版本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rbenv install 2.7.6</span></span>
<span class="line"><span>$ rbenv global 2.7.6</span></span>
<span class="line"><span>切换完成 Ruby 版本后，再次重启 Terminal，再次运行 ruby --version 命令，确定 Ruby</span></span></code></pre></div><p>版本是否切换成功。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/8.png" alt=""></a></p><h3 id="gem-和-bundler" tabindex="-1">Gem 和 Bundler <a class="header-anchor" href="#gem-和-bundler" aria-label="Permalink to &quot;Gem 和 Bundler&quot;">​</a></h3><p>第五步，是切换 Ruby 包管理工具的镜像源。</p><p>Ruby 有两种常用包管理工具，Gem 和 Bundler。这两种包管理工具都会用到，因此需要将这两种包管理工具的镜像源都切换到国内。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>切换 Gem 镜像源的方法是通过 gem sources 命令进行切换，命令如下：</span></span>
<span class="line"><span>$ gem sources --add https://gems.ruby-china.com/ --remove https://rubygems.org/</span></span>
<span class="line"><span>$ gem sources -l</span></span>
<span class="line"><span>https://gems.ruby-china.com</span></span></code></pre></div><p>这里我们使用 Ruby China 提供的镜像源进行安装。</p><p>切换 Bundler 镜像源的方法是通过设置 config 进行切换，命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bundle config mirror.https://rubygems.org https://gems.ruby-china.com</span></span>
<span class="line"><span>具体来说，它会在 Bundler 的全局配置中添加一个 mirror.https://rubygems.org 的参</span></span>
<span class="line"><span>数，将其值设置为 https://gems.ruby-china.com，表示在下载和安装包时使用</span></span></code></pre></div><p>Ruby China 的镜像源地址。</p><h2 id="xcode" tabindex="-1">Xcode <a class="header-anchor" href="#xcode" aria-label="Permalink to &quot;Xcode&quot;">​</a></h2><p>第六步，是安装和配置 Xcode。</p><p>安装 Xcode 有两种方法：</p><ul><li><p>从 Mac App Store 中进行安装</p></li><li><p>从开发者中心进行下载和安装</p></li></ul><p>如果你的网络较好，你可以使用 Mac App Store 进行安装。打开 App Store，搜索 Xcode 进行下载。下载完成后，App Store 会自动帮你安装 Xcode。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/9.png" alt=""></a></p><p>但如果你的网络不好，从 Mac App Store 下载完成后，就会一直显示“正在等待…”。这是因为从 Xcode 的安装还依赖网络校验，网络校验不通过就会一直显示“正在等待…”。当出现这种情况时，你可以长按图标删除 Xcode，然后到开发者下载中心进行下载和安装。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/10.png" alt=""></a></p><p>第二种方法就是从开发者中心进行下载。</p><p>从开发者中心进行下载需要一个 Apple ID，你需要自己申请一个，免费的就行。申请完成后，填写账号密码，登录开发者中心。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/11.png" alt=""></a></p><p>在开发者中心搜索 Xcode，并找到你电脑操作系统版本所支持的 Xcode。因为我那台 16 年电脑的系统版本是 12.6.3，所以我下载的是 Xcode 14.0.1。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/12.png" alt=""></a></p><p>下载完成后，双击安装，点击 Agree，输入密码开始安装。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/13.png" alt=""></a></p><p>安装时，勾选默认的选项进行安装即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/14.png" alt=""></a></p><p>默认项安装完成后，找到左上角的 Xcode 标识，点击 Preferences。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/15.png" alt=""></a></p><p>找到 Locations 标签中的 Command Line Tools 一栏，选择对应的 Xcode。选择完成后，会出</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现类似 /Applications/Xcode.app 之类的地址，你可以点进去，确定 Xcode 的目录地址</span></span></code></pre></div><p>是否正确。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/16.png" alt=""></a></p><p>确定完成后，就完成了 Xcode 的安装和配置。</p><h3 id="cocoapods" tabindex="-1">CocoaPods <a class="header-anchor" href="#cocoapods" aria-label="Permalink to &quot;CocoaPods&quot;">​</a></h3><p>第七步，是安装 CocoaPods。</p><p>在前面我们提到过，Ruby 有两种常用包管理工具，Gem 和 Bundler。CocoaPods 是另一种包管理工具，它虽然是用 Ruby 编写的，但不是 Ruby 的包管理工具，而是 iOS 的包管理工具。</p><p>这里我们借助 Gem 来安装 CocoaPods。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo gem install cocoapods</span></span></code></pre></div><p>安装完成后，运行如下命令确定 CocoaPods 是否已经安装成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pod --version</span></span>
<span class="line"><span>1.11.3</span></span></code></pre></div><h2 id="新建项目" tabindex="-1">新建项目 <a class="header-anchor" href="#新建项目" aria-label="Permalink to &quot;新建项目&quot;">​</a></h2><p>第七步，是新建一个 React Native 项目。</p><p>这里我们借助 React Native 内置的命令行工具，来创建一个名为 “AwesomeProject” 的新项目。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx react-native init AwesomeProject</span></span></code></pre></div><p>但是，在 “Installing CocoaPods dependencies” 这一步会出现错误，错误截图如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/17.png" alt=""></a></p><p>这是由于没有切换 CocoaPods 的镜像源导致的。解决方案是，切换到清华大学开源软件镜像站的镜像，切换方式如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cd ~/.cocoapods/repos</span></span>
<span class="line"><span>$ pod repo remove master</span></span>
<span class="line"><span>$ git clone https://mirrors.tuna.tsinghua.edu.cn/git/CocoaPods/Specs.git master</span></span>
<span class="line"><span>执行完上述命令后，进入 AwesomeProject/ios 目录，找到 Podfile 文件，在文件第一行添</span></span></code></pre></div><p>加：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source &#39;https://mirrors.tuna.tsinghua.edu.cn/git/CocoaPods/Specs.git&#39;</span></span>
<span class="line"><span>这时，再在 AwesomeProject/ios 目录下，运行 CocoaPods 安装命令即可。</span></span>
<span class="line"><span>$ bundle exec pod install</span></span></code></pre></div><p>但是，此时仍可能会遇到报错，报错内容如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/18.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报错的内容是，无法访问地址 https://github.com/lblasa/double-</span></span>
<span class="line"><span>conversion.git。</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是因为，即便配置了镜像，但镜像提供的地址仍然是 GitHub 地址。执行 pod install</span></span></code></pre></div><p>时，没有访问到 GitHub 地址。那么该怎么办呢？</p><p>解决方案是，我们可以把所有的 GitHub 地址替换成 Gitee 地址，主要有以下四步（该方案由群友柯察提供）：</p><ul><li><p>将 GitHub 仓库导入到 Gitee1.</p></li><li><p>将 GitHub 地址的相关配置，手动替换为 Gitee 地址2.</p></li><li><p>重新 pod install3.</p></li><li><p>4.如遇报错，继续重复上述步骤</p></li></ul><p>下面我们逐个步骤看一下。</p><p>第一步，将 GitHub 仓库导入到 Gitee。</p><p>首先，登录 Gitee。从右上角的 “+” 号中找到“从 GitHub/GitLab 导入仓库”的功能。填写对应的 GitHub 地址，然后点击导入。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/19.png" alt=""></a></p><p>接着，进入该仓库后，找到 “克隆 / 下载” 按钮，复制其 HTTPS 地址，示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gitee.com/jhwleo/double-conversion.git</span></span></code></pre></div><p>然后，为了方便克隆该仓库地址，你还需要将其从私有仓库设置为开源仓库。你需要先点击进入管理标签页，填写介绍，选择开源，并勾选公开须知，然后点击保存。设置方法见下图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/20.png" alt=""></a></p><p>第二步，将 GitHub 地址的相关配置，手动替换为 Gitee 地址，详细操作如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首先，使用 VSCode 编辑器，打开目录 ~/.cocoapods/repos/master。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/21.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/21.png" alt=""></a></p><p>然后，点击 Search 一栏，将 GitHub 地址替换成 Gitee 地址。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Github地址：github.com/lblasa/double-conversion.git</span></span>
<span class="line"><span>Gitee地址：gitee.com/jhwleo/double-conversion.git</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/22.png" alt=""></a></p><p>第三步，重新 pod install。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>由于下载地址已经改成了 Gitee，再次运行 pod install 时，就不会遇到 double-</span></span></code></pre></div><p>conversion 库无法访问的报错了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/23.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/23.png" alt=""></a></p><p>你可以看到，上图中的 Flipper-DoubleConversion(double-conversion) 库，在第二次安装的时候，已经安装成功。但是，我们又遇到了其他库的网络错误。</p><p>因此，第四步是不断重复前三步的，我们现在要做的就是将所有下载不了的 GitHub 地址都逐一替换成 Gitee 地址，完成 pod install 的步骤。</p><p>当然，由于在上述方案中，你需要一个个手动地进行更改和重试。所以建议有条件的同学，还是通过保持网络畅通的方式进行下载更为方便。</p><h2 id="启动项目" tabindex="-1">启动项目 <a class="header-anchor" href="#启动项目" aria-label="Permalink to &quot;启动项目&quot;">​</a></h2><p>最后一步是启动 React Native 项目。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在上一步中，我们通过 npx react-native init 命令创建了一个名为 “AwesomeProject”</span></span></code></pre></div><p>的新项目。现在，我们进入该项目目录，运行如下命令来启动 iOS 项目。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx react-native run-ios</span></span></code></pre></div><p>命令运行后，会自动启动模拟器并加载项目。你可以看到如下界面：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/24.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%258A%25A0%25E9%25A4%2590-%25E9%259B%2586%25E4%25B8%25AD%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%259A%25E8%25AF%25A6%25E8%25A7%25A3iOS%25E7%258E%25AF%25E5%25A2%2583%25E6%2590%25AD%25E5%25BB%25BA/24.png" alt=""></a></p><p>至此，我们已经成功搭建了 React Native 的开发环境，并成功运行了一个 React Native 项目。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>搭建开发环境是很多新同学的痛点，这一步劝退了很多想学习 React Native 的新同学。</p><p>在这节课中，我给你介绍了一种不借助网络工具搭建 React Native 环境的方法。它主要包括八个步骤，涉及了 Homebrew、Node、Watchman、Ruby、Gem、Bundler、Xcode、CocoaPods 的安装或镜像配置方案，以及如何新建项目和启动项目。</p><p>希望能对你有所帮助。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你在搭建 React Native 环境的过程中，遇到过哪些问题，能把你的解决方案和大家分享分享吗？</p><p>期待你的输出，如果觉得有所收获，也欢迎你把今天的内容分享给更多的朋友！</p>`,146)])])}const g=a(i,[["render",n]]);export{r as __pageData,g as default};
